/// Build `Quot.ind.{u} alpha r beta f major`.
fn mk_quot_ind(u: &Level, alpha: &Expr, r: &Expr, beta: &Expr, f: &Expr, major: &Expr) -> Expr {
    Expr::app(
        Expr::app(
            Expr::app(
                Expr::app(
                    Expr::app(
                        Expr::const_(Name::from_string("Quot.ind"), vec![u.clone()]),
                        alpha.clone(),
                    ),
                    r.clone(),
                ),
                beta.clone(),
            ),
            f.clone(),
        ),
        major.clone(),
    )
}

#[test]
fn test_quot_ind_reduction_basic() {
    // Test the quotient induction reduction rule:
    // Quot.ind α r β f (Quot.mk α r a) → f a

    let env = Environment::with_quot();
    let tc = TypeChecker::new(&env);

    let u = Level::param(Name::from_string("u"));

    // Dummy values for α, r, β
    let alpha = Expr::type_();
    let r = Expr::lam(
        BinderInfo::Default,
        Expr::type_(),
        Expr::lam(BinderInfo::Default, Expr::bvar(0), Expr::prop()),
    );
    // β : @Quot α r → Prop (simplified to constant function for testing)
    let beta = Expr::lam(BinderInfo::Default, Expr::type_(), Expr::prop());

    // f : ∀ a : α, β (Quot.mk α r a) — simplified to identity-like for testing
    // f returns Prop regardless, so use identity
    let f = Expr::lam(BinderInfo::Default, Expr::type_(), Expr::bvar(0));

    // a : α (some value - use Prop as a stand-in)
    let a = Expr::prop();

    // Build Quot.mk α r a
    let mk_app = mk_quot_mk(&u, &alpha, &r, &a);

    // Build Quot.ind α r β f (Quot.mk α r a)
    let ind_app = mk_quot_ind(&u, &alpha, &r, &beta, &f, &mk_app);

    // Reduce to WHNF - should get f a, which then beta reduces to a
    let result = tc.whnf(&ind_app);

    // The result should be 'a' (which is Prop in our test)
    // f is the identity function, so f a = a
    // After beta reduction: (λ x. x) Prop → Prop
    assert!(result.is_prop(), "Expected Prop, got {result:?}");
}

