#[test]
fn test_quot_ind_trailing_args() {
    let env = Environment::with_quot();
    let tc = TypeChecker::new(&env);

    let u = Level::param(Name::from_string("u"));
    let alpha = Expr::type_();
    let r = Expr::lam(
        BinderInfo::Default,
        Expr::type_(),
        Expr::lam(BinderInfo::Default, Expr::bvar(0), Expr::prop()),
    );
    let beta = Expr::lam(BinderInfo::Default, Expr::type_(), Expr::prop());
    let f = Expr::lam(
        BinderInfo::Default,
        Expr::type_(),
        Expr::lam(BinderInfo::Default, Expr::type_(), Expr::bvar(0)),
    );
    let a = Expr::prop();
    let extra = Expr::prop();

    let mk_app = mk_quot_mk(&u, &alpha, &r, &a);
    let ind_app = mk_quot_ind(&u, &alpha, &r, &beta, &f, &mk_app);
    let ind_with_trailing = Expr::app(ind_app, extra.clone());

    let result = tc.whnf(&ind_with_trailing);
    assert_eq!(
        result, extra,
        "Quot.ind should apply trailing args after reducing Quot.mk"
    );
}

