/// Build `Quot.mk.{u} alpha r a`.
fn mk_quot_mk(u: &Level, alpha: &Expr, r: &Expr, a: &Expr) -> Expr {
    Expr::app(
        Expr::app(
            Expr::app(
                Expr::const_(Name::from_string("Quot.mk"), vec![u.clone()]),
                alpha.clone(),
            ),
            r.clone(),
        ),
        a.clone(),
    )
}

/// Build `Quot.lift.{u v} alpha r beta f h major`.
fn mk_quot_lift(
    u: &Level,
    v: &Level,
    alpha: &Expr,
    r: &Expr,
    beta: &Expr,
    f: &Expr,
    h: &Expr,
    major: &Expr,
) -> Expr {
    Expr::app(
        Expr::app(
            Expr::app(
                Expr::app(
                    Expr::app(
                        Expr::app(
                            Expr::const_(
                                Name::from_string("Quot.lift"),
                                vec![u.clone(), v.clone()],
                            ),
                            alpha.clone(),
                        ),
                        r.clone(),
                    ),
                    beta.clone(),
                ),
                f.clone(),
            ),
            h.clone(),
        ),
        major.clone(),
    )
}

/// Standard dummy relation `fun (x : Type) (y : x) => Prop`.
fn dummy_relation() -> Expr {
    Expr::lam(
        BinderInfo::Default,
        Expr::type_(),
        Expr::lam(BinderInfo::Default, Expr::bvar(0), Expr::prop()),
    )
}

#[test]
fn test_quot_lift_trailing_args() {
    let env = Environment::with_quot();
    let tc = TypeChecker::new(&env);

    let u = Level::param(Name::from_string("u"));
    let v = Level::param(Name::from_string("v"));
    let alpha = Expr::type_();
    let r = dummy_relation();
    let beta = Expr::pi(BinderInfo::Default, Expr::type_(), Expr::type_());
    let f = Expr::lam(
        BinderInfo::Default,
        Expr::type_(),
        Expr::lam(BinderInfo::Default, Expr::type_(), Expr::bvar(0)),
    );
    let a = Expr::prop();
    let extra1 = Expr::lam(BinderInfo::Default, Expr::type_(), Expr::bvar(0));
    let extra2 = Expr::prop();

    let mk_app = mk_quot_mk(&u, &alpha, &r, &a);
    let lift_app = mk_quot_lift(&u, &v, &alpha, &r, &beta, &f, &Expr::prop(), &mk_app);
    let lift_with_trailing = Expr::app(Expr::app(lift_app, extra1), extra2.clone());

    let result = tc.whnf(&lift_with_trailing);
    assert_eq!(
        result, extra2,
        "Quot.lift should apply trailing args after reducing Quot.mk"
    );
}

