#[test]
fn test_quot_lift_non_identity_function() {
    let env = Environment::with_quot();
    let tc = TypeChecker::new(&env);

    let u = Level::param(Name::from_string("u"));
    let v = Level::zero();
    let alpha = Expr::type_();
    let r = dummy_relation();
    // f is a constant function: fun (_ : Type) => Prop
    let f = Expr::lam(BinderInfo::Default, Expr::type_(), Expr::prop());
    let a = Expr::type_();

    let mk_app = mk_quot_mk(&u, &alpha, &r, &a);
    let lift_app = mk_quot_lift(
        &u,
        &v,
        &alpha,
        &r,
        &Expr::prop(),
        &f,
        &Expr::prop(),
        &mk_app,
    );
    let result = tc.whnf(&lift_app);

    assert_eq!(
        result,
        Expr::prop(),
        "Quot.lift with constant f should reduce to Prop"
    );
    assert!(
        result != a,
        "Result should differ from the representative when f ignores its input"
    );
}

#[test]
fn test_quot_lift_multiple_reductions() {
    let env = Environment::with_quot();
    let tc = TypeChecker::new(&env);

    let u = Level::param(Name::from_string("u"));
    let v = Level::param(Name::from_string("v"));
    let alpha = Expr::type_();
    let r = dummy_relation();
    let id = Expr::lam(BinderInfo::Default, Expr::type_(), Expr::bvar(0));
    let a = Expr::prop();

    // Inner: Quot.lift id h2 (Quot.mk r a) -> a
    let inner_mk = mk_quot_mk(&u, &alpha, &r, &a);
    let inner_lift = mk_quot_lift(&u, &v, &alpha, &r, &alpha, &id, &Expr::type_(), &inner_mk);

    // Outer: Quot.lift id h1 (Quot.mk r inner_lift) -> inner_lift -> a
    let outer_mk = mk_quot_mk(&u, &alpha, &r, &inner_lift);
    let outer_lift = mk_quot_lift(&u, &v, &alpha, &r, &alpha, &id, &Expr::prop(), &outer_mk);
    let result = tc.whnf(&outer_lift);

    assert_eq!(
        result, a,
        "Nested Quot.lift should reduce through both quotient layers"
    );
}

#[test]
fn test_quot_constants_have_correct_types() {
    let env = Environment::with_quot();
    let tc = TypeChecker::new(&env);

    for name in ["Quot", "Quot.mk", "Quot.lift", "Quot.ind"] {
        let info = env
            .get_const(&Name::from_string(name))
            .unwrap_or_else(|| panic!("{name} should exist in Environment::with_quot()"));
        let type_whnf = tc.whnf(&info.type_);
        assert!(
            type_whnf.is_pi(),
            "{name} should have a Pi type, got {type_whnf:?}"
        );
    }
}
